        public ToolResultSpec copy() {
            ToolResultSpec copied = new ToolResultSpec(description, fields);
            copied.setSchema(schema);
            return copied;
        }
    }

    public static final class ToolParamSpec {
        private String name;
        private String type;
        private boolean required;
        private String description;
        private String title;
        private List<String> examples = new ArrayList<>();
        private JsonNode schema;

        public ToolParamSpec(String name, String type, boolean required, String description) {
            this(name, type, required, description, null, null, null);
        }

        public ToolParamSpec(String name, String type, boolean required, String description, String title, List<String> examples) {
            this(name, type, required, description, title, examples, null);
        }

        public ToolParamSpec(String name, String type, boolean required, String description, String title, List<String> examples, JsonNode schema) {
            this.name = name;
            this.type = type;
            this.required = required;
            this.description = description;
            this.title = title;
            if (examples != null && !examples.isEmpty()) {
                this.examples.addAll(examples);
            }
            this.schema = schema == null ? null : schema.deepCopy();
        }

        public String getName() {
            return name;
        }

        public String getType() {
            return type;
        }

        public boolean isRequired() {
            return required;
        }

        public String getDescription() {
            return description;
        }

        public void setDescription(String description) {
            this.description = description;
        }

        public String getTitle() {
            return title;
        }

        public List<String> getExamples() {
            return examples;
        }

        public JsonNode getSchema() {
