package com.allthinkstars.framework.iot.ai.tools.annotated;

import com.allthinkstars.framework.iot.ai.tools.ToolArgsInvalidException;
import com.allthinkstars.framework.iot.ai.tools.ToolExecException;
import com.allthinkstars.framework.iot.ai.tools.support.AiRunContext;
import com.allthinkstars.framework.iot.ai.tools.support.AiToolPageSupport;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolComponent;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolDef;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolParam;
import com.allthinkstars.framework.iot.ai.tools.vo.AiProductionPlanToolVo;
import com.allthinkstars.framework.iot.app.dto.PlanQueryParam;
import com.allthinkstars.framework.iot.app.service.AppProdPlanService;
import com.allthinkstars.framework.iot.erp.dto.CastingProductionPlanDto;
import com.allthinkstars.framework.iot.erp.service.atsi.CastingProductionPlanManageService;
import com.allthinkstars.framework.iot.erp.vo.CastingProductionPlanPageVo;
import com.baomidou.mybatisplus.core.metadata.IPage;
import com.ruoyi.common.core.domain.PageQuery;
import lombok.RequiredArgsConstructor;
import org.apache.commons.lang3.StringUtils;

import java.time.LocalDate;

/**
 * 生产计划 AI 工具
 * 这里复用现有计划查询与详情服务，只在工具层完成参数映射和 AI 友好的结果裁剪
 */
@RequiredArgsConstructor
@AiToolComponent
public class AiProductionPlanTools {

    private final AppProdPlanService appProdPlanService;
    private final CastingProductionPlanManageService planManageService;

    @AiToolDef(
        value = "查询当前工厂内的生产计划列表适用于按计划名称、炉号、日期范围或状态筛选计划",
        title = "查询生产计划",
        outputDescription = "生产计划列表查询结果, 返回值中重量相关的字段, 单位均为 kg, 耗电量单位均为 kWh"
    )
    public AiProductionPlanToolVo.SearchResult production_plan_search(
        @AiToolParam(
            name = "planName",
            value = "计划名称，可选；用于按计划名称筛选",
            title = "计划名称",
            examples = {"白班计划", "球铁计划"}
        ) String planName,
        @AiToolParam(
            name = "fnCode",
            value = "工厂炉号编码，可选；等价于现有计划查询中的 furnaceCode",
            title = "炉号",
            examples = {"A", "1", "2"}
        ) String fnCode,
        @AiToolParam(
            name = "startDate",
            value = "查询起始日期，格式 YYYY-MM-DD",
            title = "开始日期",
            examples = {"2026-03-17"}
        ) String startDate,
        @AiToolParam(
            name = "endDate",
            value = "查询结束日期，格式 YYYY-MM-DD",
            title = "结束日期",
            examples = {"2026-03-17"}
        ) String endDate,
        @AiToolParam(
            name = "status",
            value = "生产计划状态，可选0=待生产，1=生产中，2=生产完成",
            title = "计划状态",
            examples = {"0", "1", "2"}
        ) Integer status,
        @AiToolParam(name = "page", value = "页码，默认1", title = "页码") Integer page,
        @AiToolParam(name = "pageSize", value = "每页数量，默认20，最大100", title = "每页数量") Integer pageSize,
        AiRunContext ctx
    ) {
        // 搜索工具只负责把 AI 参数映射到既有查询服务，避免维护第二套计划查询逻辑
        PlanQueryParam queryParam = new PlanQueryParam();
        queryParam.setPlanName(normalizeText(planName));
        queryParam.setKeyword(normalizeText(fnCode));
        queryParam.setStartDate(parseDate(startDate, "startDate"));
        queryParam.setEndDate(parseDate(endDate, "endDate"));
        queryParam.setStatus(status);

        int pageNumber = AiToolPageSupport.normalizePage(page);
        int normalizedPageSize = AiToolPageSupport.normalizePageSize(pageSize);
        PageQuery pageQuery = new PageQuery();
        pageQuery.setPageNum(pageNumber);
        pageQuery.setPageSize(normalizedPageSize);

        IPage<CastingProductionPlanPageVo> pageResult = appProdPlanService.queryPlanPageList(queryParam, pageQuery);
        return AiProductionPlanToolVo.SearchResult.from(pageResult, pageNumber, normalizedPageSize);
    }

    @AiToolDef(
        value = "查询单个生产计划详情，返回计划主信息和炉次计划摘要",
        title = "查询生产计划详情",
        outputDescription = "生产计划详情结果, 返回值中重量相关的字段, 单位均为 kg, 耗电量单位均为 kWh"
    )
    public AiProductionPlanToolVo.DetailResult production_plan_detail(
        @AiToolParam(
            name = "planId",
            value = "生产计划唯一 ID",
            title = "计划ID",
            examples = {"12345"},
            required = true
        ) Long planId,
        AiRunContext ctx
    ) {
        // 详情继续复用既有 DTO 查询链路，但对返回结果做摘要裁剪，避免把包次重字段提前暴露给模型
        CastingProductionPlanDto detail = planManageService.planDetail(planId);
        if (detail == null || detail.getPlanId() == null) {
            throw new ToolExecException("tool_exec_failed", "未找到对应生产计划，planId=" + planId);
        }

        return AiProductionPlanToolVo.DetailResult.from(detail);
    }

    private LocalDate parseDate(String raw, String fieldName) {
        String normalized = normalizeText(raw);
        if (normalized == null) {
            return null;
        }
        try {
            return LocalDate.parse(normalized);
        } catch (Exception e) {
            throw new ToolArgsInvalidException("参数类型不匹配: " + fieldName);
        }
    }

    private String normalizeText(String value) {
        if (StringUtils.isBlank(value)) {
            return null;
        }
        return value.trim();
    }
}

