package com.allthinkstars.framework.iot.ai.tools.annotated;

import com.allthinkstars.framework.iot.ai.tools.ToolArgsInvalidException;
import com.allthinkstars.framework.iot.ai.tools.ToolArgsMissingException;
import com.allthinkstars.framework.iot.ai.tools.ToolExecException;
import com.allthinkstars.framework.iot.ai.tools.report.AiFurnaceBatchDetailProjectionService;
import com.allthinkstars.framework.iot.ai.tools.report.AiFurnaceBatchOverviewReport;
import com.allthinkstars.framework.iot.ai.tools.report.AiFurnaceBatchOverviewReportService;
import com.allthinkstars.framework.iot.ai.tools.support.AiRunContext;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolComponent;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolDef;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolParam;
import com.allthinkstars.framework.iot.ai.tools.vo.AiFurnaceBatchDetailToolVo;
import com.allthinkstars.framework.iot.nextg.entity.TbCastingFurnaceChargeBatch;
import com.allthinkstars.framework.iot.nextg.entity.TbDeviceFurnace;
import com.allthinkstars.framework.iot.nextg.mapper.TbCastingFurnaceChargeBatchMapper;
import com.allthinkstars.framework.iot.nextg.mapper.TbDeviceFurnaceMapper;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import lombok.RequiredArgsConstructor;

import java.time.LocalDate;
import java.util.*;

/**
 * Cost-related tools exposed to the model via {@link AiToolDef} annotations.
 */
@RequiredArgsConstructor
@AiToolComponent
public class AiFurnaceBatchTools {

    private final TbDeviceFurnaceMapper tbDeviceFurnaceMapper;
    private final TbCastingFurnaceChargeBatchMapper tbCastingFurnaceChargeBatchMapper;
    private final AiFurnaceBatchOverviewReportService overviewReportService;
    private final AiFurnaceBatchDetailProjectionService detailProjectionService;
    private final ObjectMapper objectMapper;

    @AiToolDef(
        value = "Query compact overview report for furnace batches on a given date or shift within the current user's tenant/device scope",
        title = "查询炉次概览",
        outputDescription = "炉次概览查询结果, 返回值中重量相关的字段, 单位均为 kg, 耗电量单位均为 kWh"
    )
    public AiFurnaceBatchOverviewReport furnace_batch_overview_report(
        @AiToolParam(
            name = "fnCode",
            value = "炉号编码（标准编码）用户说“1号炉/炉号1/1#”时应解析为 fnCode=1",
            required = true,
            title = "炉号",
            examples = {"1", "2", "3", "6", "10", "A", "B"}
        ) String fnCode,
        @AiToolParam(
            name = "date",
            value = "目标日期，格式 YYYY-MM-DD；可选，不传默认今天；传 shiftId 时可省略",
            title = "日期",
            examples = {"2026-03-05"},
            required = true
        ) String date,
        @AiToolParam(
            name = "shiftId",
            value = "班次ID；可选，传入时优先按班次查询",
            title = "班次ID"
        ) Long shiftId,
        AiRunContext ctx
    ) {
        List<Long> didList = resolveVisibleDeviceIds(ctx);
        List<Long> deptIds = resolveVisibleDeptIds(ctx);
        if (didList.isEmpty() && deptIds.isEmpty()) {
            throw new ToolExecException("empty_scope", "上下文未包含可见设备/工厂范围，拒绝查询炉次概览");
        }
        if (fnCode == null || fnCode.trim().isEmpty()) {
            throw new ToolArgsMissingException("fnCode");
        }

        LocalDate targetDate;
        if (shiftId != null) {
            targetDate = null;
        } else if (date == null || date.isBlank()) {
            targetDate = LocalDate.now();
        } else {
            try {
                targetDate = LocalDate.parse(date.trim());
            } catch (Exception e) {
                throw new ToolArgsInvalidException("date格式错误(YYYY-MM-DD): " + date);
            }
        }

        List<TbDeviceFurnace> candidates = findFurnacesByFnCode(ctx, fnCode.trim());
        if (candidates.isEmpty()) {
            throw new ToolExecException("tool_exec_failed", "未找到匹配炉体，fnCode=" + fnCode.trim());
        }
        if (candidates.size() > 1) {
            ObjectNode data = objectMapper.createObjectNode();
            data.put("fnCode", fnCode.trim());
            data.put("candidateCount", candidates.size());
            ArrayNode candidateArr = objectMapper.createArrayNode();
            for (TbDeviceFurnace candidate : candidates) {
                ObjectNode item = objectMapper.createObjectNode();
                item.put("deviceInternalId", candidate.getDeviceInternalId());
                item.put("furnaceNo", candidate.getFnNo());
                item.put("furnaceCode", candidate.getFnCode());
                item.put("ownerDeptId", candidate.getOwnerDeptId());
                candidateArr.add(item);
            }
            data.set("candidates", candidateArr);
            throw new ToolExecException("tool_exec_failed", "fnCode匹配到多个炉体，请提供更精确条件", data);
        }

        TbDeviceFurnace targetFurnace = candidates.get(0);
        try {
            return overviewReportService.buildReport(
                targetFurnace,
                targetDate == null ? LocalDate.now() : targetDate,
                shiftId,
                ctx == null ? null : ctx.getTenantId()
            );
        } catch (Exception e) {
            throw new ToolExecException("tool_exec_failed", e.getMessage());
        }
    }

    @AiToolDef(
        value = "查询炉体的某个炉次具体的生产数据, 比如投料重量 / 加料重量, 出炉重量, 元素测量 / 碳硅分析 / 光谱检测结果, 喂丝数据, 炉次耗电量, 生产包次等生产数据等",
        title = "查询炉次生产数据",
        outputDescription = "单个炉次详情结果, 返回值中重量相关的字段, 单位均为 kg, 耗电量单位均为 kWh"
    )
    public AiFurnaceBatchDetailToolVo.DetailResult furnace_batch_detail(
        @AiToolParam(
            name = "batchId",
            value = "优先使用炉次ID（来自 today_furnace_batches 结果 detailQuery）",
            title = "炉次ID",
            examples = {"123456"}
        ) String batchId,
        @AiToolParam(
            name = "fnCode",
            value = "炉号编码；当 batchId 缺失时必填用户说“1号炉/炉号1/1#”时应解析为 fnCode=1",
            title = "炉号",
            examples = {"1", "2", "3", "6", "1号炉", "炉号1", "1#"}
        ) String fnCode,
        @AiToolParam(
            name = "date",
            value = "炉次日期，格式 YYYY-MM-DD；当 batchId 缺失时必填",
            title = "日期",
            examples = {"2026-03-05", "今天", "昨日", "昨天", "前天"}
        ) String date,
        @AiToolParam(
            name = "batchNo",
            value = "炉次序号（正整数）；当 batchId 缺失时必填",
            title = "炉次序号",
            examples = {"1", "2", "3"}
        ) Integer batchNo,
        AiRunContext ctx
    ) {
        List<Long> didList = resolveVisibleDeviceIds(ctx);
        List<Long> deptIds = resolveVisibleDeptIds(ctx);
        if (didList.isEmpty() && deptIds.isEmpty()) {
            throw new ToolExecException("empty_scope", "上下文未包含可见设备/工厂范围，拒绝查询炉次详情");
        }

        String normalizedBatchId = normalizeText(batchId);
        TbCastingFurnaceChargeBatch batch;
        TbDeviceFurnace targetFurnace = null;
        if (normalizedBatchId != null) {
            Long numericBatchId;
            try {
                numericBatchId = Long.parseLong(normalizedBatchId);
            } catch (NumberFormatException ex) {
                throw new ToolArgsInvalidException("batchId必须为数字ID: " + normalizedBatchId);
            }
            batch = tbCastingFurnaceChargeBatchMapper.selectById(numericBatchId);
            if (batch == null) {
                throw new ToolExecException("tool_exec_failed", "未找到对应炉次，batchId=" + normalizedBatchId);
            }
            if (!isVisibleBatch(batch, didList, deptIds)) {
                throw new ToolExecException("tool_exec_failed", "该炉次不在当前可见设备/工厂范围内");
            }
            targetFurnace = findFurnaceByDidAndFn(ctx, batch.getDeviceInternalId(), batch.getFurnaceNo());
        } else {
            if (normalizeText(fnCode) == null) {
                throw new ToolArgsMissingException("fnCode");
            }
            if (normalizeText(date) == null) {
                throw new ToolArgsMissingException("date");
            }
            if (batchNo == null) {
                throw new ToolArgsMissingException("batchNo");
            }
            LocalDate targetDate;
            try {
                targetDate = LocalDate.parse(date.trim());
            } catch (Exception e) {
                throw new ToolArgsInvalidException("date格式错误(YYYY-MM-DD): " + date);
            }
            if (batchNo.intValue() <= 0) {
                throw new ToolArgsInvalidException("batchNo必须为正整数");
            }
            List<TbDeviceFurnace> candidates = findFurnacesByFnCode(ctx, fnCode.trim());
            if (candidates.isEmpty()) {
                throw new ToolExecException("tool_exec_failed", "未找到匹配炉体，fnCode=" + fnCode.trim());
            }
            if (candidates.size() > 1) {
                ObjectNode data = objectMapper.createObjectNode();
                data.put("fnCode", fnCode.trim());
                data.put("candidateCount", candidates.size());
                ArrayNode candidateArr = objectMapper.createArrayNode();
                for (TbDeviceFurnace candidate : candidates) {
                    ObjectNode item = objectMapper.createObjectNode();
                    item.put("deviceInternalId", candidate.getDeviceInternalId());
                    item.put("furnaceNo", candidate.getFnNo());
                    item.put("furnaceCode", candidate.getFnCode());
                    item.put("ownerDeptId", candidate.getOwnerDeptId());
                    candidateArr.add(item);
                }
                data.set("candidates", candidateArr);
                throw new ToolExecException("tool_exec_failed", "fnCode匹配到多个炉体，请提供更精确条件", data);
            }
            targetFurnace = candidates.get(0);
            batch = tbCastingFurnaceChargeBatchMapper.findByBatchKey(
                targetFurnace.getDeviceInternalId(),
                targetFurnace.getFnNo(),
                targetDate,
                batchNo
            );
            if (batch == null) {
                throw new ToolExecException(
                    "tool_exec_failed",
                    "未找到对应炉次，fnCode=" + fnCode.trim() + ", date=" + targetDate + ", batchNo=" + batchNo
                );
            }
        }

        return detailProjectionService.buildDetail(targetFurnace, batch);
    }

    private TbDeviceFurnace findFurnaceByDidAndFn(AiRunContext ctx, Long did, Integer fnNo) {
        if (did == null || fnNo == null) {
            return null;
        }
        List<TbDeviceFurnace> source = new ArrayList<>();
        List<Long> didList = resolveVisibleDeviceIds(ctx);
        if (!didList.isEmpty()) {
            source.addAll(tbDeviceFurnaceMapper.selectListByDidList(didList));
        }
        List<Long> deptIds = resolveVisibleDeptIds(ctx);
        for (Long deptId : deptIds) {
            if (deptId == null) {
                continue;
            }
            List<TbDeviceFurnace> furnaces = tbDeviceFurnaceMapper.selectAllByFactory(deptId);
            if (furnaces != null && !furnaces.isEmpty()) {
                source.addAll(furnaces);
            }
        }
        for (TbDeviceFurnace furnace : source) {
            if (furnace == null) {
                continue;
            }
            if (Objects.equals(furnace.getDeviceInternalId(), did) && Objects.equals(furnace.getFnNo(), fnNo)) {
                return furnace;
            }
        }
        return null;
    }

    private boolean isVisibleBatch(TbCastingFurnaceChargeBatch batch, List<Long> didList, List<Long> deptIds) {
        if (batch == null) {
            return false;
        }
        boolean visibleByDid = batch.getDeviceInternalId() != null && didList.contains(batch.getDeviceInternalId());
        boolean visibleByDept = batch.getDeptId() != null && deptIds.contains(batch.getDeptId());
        return visibleByDid || visibleByDept;
    }

    private String normalizeText(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }

    private List<TbDeviceFurnace> findFurnacesByFnCode(AiRunContext ctx, String fnCode) {
        List<TbDeviceFurnace> source = new ArrayList<>();
        List<Long> didList = resolveVisibleDeviceIds(ctx);
        if (!didList.isEmpty()) {
            source.addAll(tbDeviceFurnaceMapper.selectListByDidList(didList));
        }

        List<Long> deptIds = resolveVisibleDeptIds(ctx);
        for (Long deptId : deptIds) {
            if (deptId == null) {
                continue;
            }
            List<TbDeviceFurnace> furnaces = tbDeviceFurnaceMapper.selectAllByFactory(deptId);
            if (furnaces != null && !furnaces.isEmpty()) {
                source.addAll(furnaces);
            }
        }

        if (source.isEmpty()) {
            return Collections.emptyList();
        }

        String normalizedFnCode = fnCode.trim();
        Map<String, TbDeviceFurnace> unique = new LinkedHashMap<>();
        for (TbDeviceFurnace furnace : source) {
            if (furnace == null || furnace.getFnCode() == null) {
                continue;
            }
            if (!normalizedFnCode.equalsIgnoreCase(furnace.getFnCode().trim())) {
                continue;
            }
            String uniqueKey = furnace.getFurnaceId();
            if (uniqueKey == null) {
                uniqueKey = furnace.getDeviceInternalId() + "|" + furnace.getFnNo();
            }
            unique.putIfAbsent(uniqueKey, furnace);
        }
        return new ArrayList<>(unique.values());
    }

    private static List<Long> resolveVisibleDeviceIds(AiRunContext ctx) {
        if (ctx == null || ctx.getVisibleDeviceInternalIds() == null) {
            return Collections.emptyList();
        }
        return ctx.getVisibleDeviceInternalIds();
    }

    private static List<Long> resolveVisibleDeptIds(AiRunContext ctx) {
        if (ctx == null) {
            return Collections.emptyList();
        }
        List<Long> deptIds = ctx.getVisibleDeptIds();
        if (deptIds != null && !deptIds.isEmpty()) {
            return deptIds;
        }
        if (ctx.getTenantId() != null) {
            return Collections.singletonList(ctx.getTenantId());
        }
        return Collections.emptyList();
    }
}

