import com.ruoyi.common.exception.ServiceException;
import lombok.RequiredArgsConstructor;

/**
 * 单据写操作的统一 prepare-confirm MCP Tool。
 *
 * <p>prepare 保留每种单据的强类型输入；confirm 只接收 preparationId，
 * CommandType 始终由具体 prepare 方法固定，模型不能自行指定执行器。</p>
 */
@AiToolComponent
@RequiredArgsConstructor
public class AiDocumentCommandTools {

    private final AiMaterialStockDocumentService materialStockDocumentService;
    private final AiErpCommandGateway erpCommandGateway;
    private final PreparedCommandService preparedCommandService;

    @AiToolDef(
        name = "prepare_furnace_stock_document",
        value = "校验并预览炉料人工入库或出库单，不写业务表。返回 preparationId 后必须等待用户确认。",
        title = "准备炉料出入库单",
        outputDescription = "带 preparationId 的炉料出入库预览"
    )
    public AiPreparedCommandResult prepareFurnaceStockDocument(
        @AiToolParam(name = "form", value = "完整炉料出入库表单", title = "炉料出入库表单", required = true)
        AiMaterialStockDocumentForm form,
        AiRunContext context
    ) {
        Long tenantId = requireContext(context);
        AiMaterialStockDocumentResult preview;
        try {
            preview = materialStockDocumentService.prepare(form, tenantId);
        } catch (ServiceException e) {
            throw new ToolArgsInvalidException(e.getMessage());
        }
        return savePrepared(
            CommandType.FURNACE_STOCK_DOCUMENT_CREATE,
            preview == null ? null : preview.getForm(),
            preview,
            context
        );
    }

    @AiToolDef(
        name = "prepare_erp_purchase_document",
        value = "校验并预览 ERP 请购单或采购订单，不写业务表。返回 preparationId 后必须等待用户确认。",
        title = "准备采购单据",
        outputDescription = "带 preparationId 的 ERP 采购单据预览"
    )
    public AiPreparedCommandResult prepareErpPurchaseDocument(
        @AiToolParam(name = "form", value = "完整采购表单", title = "采购表单", required = true)
        AiErpPurchaseDocumentForm form,
        AiRunContext context
    ) {
        AiErpToolResult preview = erpCommandGateway.preparePurchase(form, context);
        // 规范化发生在 iot-erp，必须保存返回的 form，不能保存 iot-app 发出的原始请求。
        return savePrepared(
            CommandType.ERP_PURCHASE_DOCUMENT_CREATE,
            preview == null ? null : preview.getForm(),
            preview,
            context
        );
    }

    @AiToolDef(
        name = "prepare_erp_product_stock_document",
        value = "校验并预览 ERP 产品采购入库、委外入库或其他入库单，不写业务表。返回 preparationId 后必须等待用户确认。",
        title = "准备产品入库单",
        outputDescription = "带 preparationId 的 ERP 产品入库预览"
    )
    public AiPreparedCommandResult prepareErpProductStockDocument(
        @AiToolParam(name = "form", value = "完整产品入库表单", title = "产品入库表单", required = true)
        AiErpStockDocumentForm form,
        AiRunContext context
    ) {
        AiErpToolResult preview = erpCommandGateway.prepareStock(form, context);
        return savePrepared(
            CommandType.ERP_PRODUCT_STOCK_DOCUMENT_CREATE,
            preview == null ? null : preview.getForm(),
            preview,
            context
        );
    }

    @AiToolDef(
        name = "prepare_erp_outsource_order",
        value = "校验并预览 ERP 委外任务及所需物料，不写业务表。返回 preparationId 后必须等待用户确认。",
        title = "准备委外订单",
        outputDescription = "带 preparationId 的 ERP 委外订单预览"
    )
    public AiPreparedCommandResult prepareErpOutsourceOrder(
        @AiToolParam(name = "form", value = "完整委外订单表单", title = "委外订单表单", required = true)
        AiErpOutsourceOrderForm form,
        AiRunContext context
    ) {
        AiErpToolResult preview = erpCommandGateway.prepareOutsource(form, context);
        return savePrepared(
            CommandType.ERP_OUTSOURCE_ORDER_CREATE,
            preview == null ? null : preview.getForm(),
            preview,
            context
        );
    }

    @AiToolDef(
        name = "confirm_prepared_command",
        value = "确认一个已经向用户展示并获得明确同意的 preparation。只允许传入 prepare 返回的 preparationId。",
        title = "确认单据",
        outputDescription = "已确认单据的创建结果"
    )
    public AiPreparedCommandResult confirmPreparedCommand(
        @AiToolParam(name = "preparationId", value = "prepare 返回的 UUID", title = "Preparation ID", required = true)
        String preparationId,
        AiRunContext context
    ) {
        return preparedCommandService.confirm(preparationId, context);
    }

    private AiPreparedCommandResult savePrepared(CommandType commandType,
                                                  Object normalizedForm,
                                                  Object preview,
                                                  AiRunContext context) {
        if (normalizedForm == null) {
            throw new ToolExecException("preparation_data_invalid", "领域 prepare 未返回规范化 form");
        }
        return preparedCommandService.prepare(commandType, normalizedForm, preview, context);
    }

    private Long requireContext(AiRunContext context) {
        if (context == null || context.getTenantId() == null) {
            throw new ToolExecException("empty_scope", "当前工厂上下文缺失，无法操作物料库存");
        }
        if (context.getSysUserId() == null) {
            throw new ToolExecException("empty_user", "当前用户上下文缺失");
        }
        return context.getTenantId();
    }
}

