package com.allthinkstars.framework.iot.ai.mcp.dispatcher;

import cn.dev33.satoken.context.SaHolder;
import com.allthinkstars.framework.iot.ai.tools.support.AiRunContext;
import com.allthinkstars.framework.iot.support.LoginSupport;
import com.allthinkstars.framework.iot.web.config.ThreadLocalHelper;
import com.ruoyi.common.core.domain.entity.SysUser;
import com.ruoyi.common.core.domain.model.LoginUser;
import com.ruoyi.common.helper.LoginHelper;
import com.ruoyi.system.service.ISysUserService;
import lombok.RequiredArgsConstructor;
import org.springframework.util.Assert;

import java.util.function.Supplier;

/**
 * 为 AI tool 调用临时建立线程内 LoginUser 上下文，
 * 仅覆盖依赖 LoginHelper.getLoginUser()/getUserId() 的存量业务逻辑
 */
@RequiredArgsConstructor
public class SaTokenAiToolLoginContextRunner implements AiToolLoginContextRunner {

    private final ISysUserService sysUserService;
    private final LoginSupport loginSupport;

    @Override
    public <T> T run(AiRunContext runContext, Supplier<T> action) {
        if (runContext == null || runContext.getSysUserId() == null) {
            return action.get();
        }
        SysUser user = sysUserService.selectUserById(runContext.getSysUserId());
        Assert.notNull(user, "AI tool run-as user not found: " + runContext.getSysUserId());

        LoginUser loginUser = loginSupport.buildLoginUser(user);
        SaHolder.getStorage().set(LoginHelper.LOGIN_USER_KEY, loginUser);
        // ERP 存量服务按 ThreadLocal 中的工厂解析 tenantId，必须与 MCP 服务端解析结果保持一致。
        ThreadLocalHelper.setOpenApiDeptId(runContext.getTenantId());
        try {
            return action.get();
        } finally {
            ThreadLocalHelper.removeOpenApiDeptId();
            SaHolder.getStorage().set(LoginHelper.LOGIN_USER_KEY, null);
        }
    }
}

