 */
@RequiredArgsConstructor
@Slf4j
@Configuration
public class SaTokenConfig implements WebMvcConfigurer {

    private static final String TOKEN_PREFIX_OF_DEVICE = "DEVICE";
    private static final String TOKEN_PREFIX_OF_DEVICE_V2 = "HMI-X-J-V2";
    private static final String TOKEN_PREFIX_OF_OPEN_API = "OPEN-API-V1";
    private static final String TOKEN_PREFIX_OF_OPEN_API_V2 = "OPEN-API-V2";
    private static final String TOKEN_PREFIX_OF_PDA = "PDA";
    private static final AtomicBoolean IS_FIRST_VALID_BIZ_REQUEST = new AtomicBoolean(true);

    private static final String HEALTHCHECK_API = "/app/healthcheck";
    /**
     * AI 内部 Store 接口仅通过 X-AI-GW-TOKEN 校验，不依赖 Sa-Token 登录态。
     */
    private static final String AI_INTERNAL_STORE_API = "/ai/internal/store/**";
    private static final String AI_INTERNAL_STORE_API_WITH_CONTEXT = "/epservice/ai/internal/store/**";
    /** AI ERP 内部接口使用独立 internal token，并由接口内恢复经服务端解析的用户与工厂上下文。 */
    private static final String AI_INTERNAL_ERP_API = "/ai/internal/erp/**";
    private static final String AI_INTERNAL_ERP_API_WITH_CONTEXT = "/epservice/ai/internal/erp/**";

    private final SecurityProperties securityProperties;
    private final StringRedisTemplate stringRedisTemplate;
    private final WeWorkSupport weWorkSupport;

    @Autowired(required = false)
    private List<ServiceCustomInterceptor> serviceCustomInterceptors;

    @Value("${spring.application.name}")
    private String appName;

    @NacosValue(value = "${sa-token.deviceApiToleranceMinutes:5}", autoRefreshed = true)
    private Integer deviceApiToleranceMinutes;

    void whenFirstValidBizRequest(SaRequest saRequest) {
        if (IS_FIRST_VALID_BIZ_REQUEST.compareAndSet(true, false)) {
            var info = "服务开始承接业务请求：" + saRequest.getRequestPath();
            this.weWorkSupport.notifyFirstValidBizRequest(info);
        }
    }

    /**
     * 注册sa-token的拦截器
     */
    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        // 注册路由拦截器，自定义验证规则
        registry.addInterceptor(new SaRouteInterceptor((request, response, handler) -> {

            // it will throw exception if match
            this.healthcheck(request, response);

            ThreadLocalHelper.removePdaCode();
            ThreadLocalHelper.removeDeviceInternalId();
            ThreadLocalHelper.removeAppKey();
            ThreadLocalHelper.removeOpenApiDeptId();

            String requestPath = request.getRequestPath();

            String token = normalizeOpenApiAuthorizationToken(request.getHeader(HttpHeaders.AUTHORIZATION));
            // Authorization Header 是正式开放接口约定；URL token 仅作为旧链路兼容兜底。
            if (StringUtils.isNotBlank(requestPath) && requestPath.startsWith("/openapi")) {
                String urlToken = normalizeOpenApiAuthorizationToken(request.getParam("token"));
                if (StringUtils.isBlank(token) && StringUtils.isNotBlank(urlToken)) {
                    token = urlToken;
                    log.info("try to get token from url param");
                }
            }

            if (Objects.nonNull(token) && token.startsWith(TOKEN_PREFIX_OF_DEVICE)) {
                verifyDevice(request, token);
                this.whenFirstValidBizRequest(request);
                return;
            }
            if (Objects.nonNull(token) && token.startsWith(TOKEN_PREFIX_OF_DEVICE_V2)) {
                verifyDeviceV2(request, token);
                this.whenFirstValidBizRequest(request);
                return;
            }
            if (Objects.nonNull(token) && token.startsWith(TOKEN_PREFIX_OF_OPEN_API)) {
                verifyOpenAPI(request, token);
                this.whenFirstValidBizRequest(request);
                return;
            }
            if (Objects.nonNull(token) && token.startsWith(TOKEN_PREFIX_OF_OPEN_API_V2)) {
                verifyOpenAPIV2(request, token);
                this.whenFirstValidBizRequest(request);
                return;
            }
            if (Objects.nonNull(token) && token.startsWith(TOKEN_PREFIX_OF_PDA)) {
                String pdaCode = verifyPda(request, token);
                ThreadLocalHelper.setPdaCode(pdaCode);
                this.whenFirstValidBizRequest(request);
                return;
            }
            if (CollectionUtils.isNotEmpty(serviceCustomInterceptors)) {
                serviceCustomInterceptors.forEach(i -> i.checkIfValidRequest(request));
            }


            ExcludeUrlProperties excludeUrlProperties = SpringUtils.getBean(ExcludeUrlProperties.class);
            SaRouter
                .match("/**")
                .notMatch(AI_INTERNAL_STORE_API)
                .notMatch(AI_INTERNAL_STORE_API_WITH_CONTEXT)
                .notMatch(AI_INTERNAL_ERP_API)
                .notMatch(AI_INTERNAL_ERP_API_WITH_CONTEXT)
                .notMatch(securityProperties.getExcludes())
                .notMatch(excludeUrlProperties.getExcludes())
                .check(StpUtil::checkLogin);
            this.whenFirstValidBizRequest(request);

        })).addPathPatterns("/**");
        registry.addInterceptor(new SaAnnotationInterceptor()).addPathPatterns("/**");
    }

    private String normalizeOpenApiAuthorizationToken(String token) {
        if (StringUtils.isBlank(token)) {
            return token;
        }
        String normalized = StringUtils.trim(token);
        if (StringUtils.startsWithIgnoreCase(normalized, "Bearer ")) {
            return StringUtils.trim(StringUtils.substring(normalized, "Bearer ".length()));
        }
        return normalized;
    }

    public interface ServiceCustomInterceptor {
        void checkIfValidRequest(SaRequest request) throws RuntimeException;
    }

    @Bean
    public StpLogic getStpLogicJwt() {
        // Sa-Token 整合 jwt (简单模式)
        return new StpLogicJwtForSimple();
    }

    /**
