     *
     * @throws BackResultException 为什么抛这个异常？参见 {@link SaRouteInterceptor#preHandle} 的逻辑。
     */
    private void healthcheck(SaRequest request, SaResponse response) throws BackResultException {
        var reqPath = request.getRequestPath();
        if (HEALTHCHECK_API.equals(reqPath)) {
            response.setStatus(HttpStatus.OK.value());
            throw new BackResultException("ok");
        }
    }

    private String getReqInfo(SaRequest request) {
        var requestPath = request.getRequestPath();
        try {
            var remoteAddr = ServletUtils.getClientIP();
            return String.format("[%s]%s", remoteAddr, requestPath);
        } catch (Exception e) {
            log.error("提取请求信息异常[{}]", requestPath, e);
            return requestPath;
        }
    }

    private void verifyOpenAPI(SaRequest request, String token) {
        var reqInfo = getReqInfo(request);

        // fixme
        // 这里需要对requestPath进行检查
        // 限制只能访问开放接口
        // 防止权限绕过

        String[] parts = token.split("\\|");
        if (parts.length < 5) {
            log.error("[{}]无效的token[{}]", reqInfo, token);
            throw new ServiceException("无效的token");
        }
        // token = prefix | deptId | nonce | ts | hmac
        String deptId = parts[1];
        String sha256 = parts[4];
        String ts = parts[3];
        long requestTimeMillis;
        try {
            requestTimeMillis = Long.parseLong(ts);
        } catch (Exception e) {
            log.error("[{}]无效的时间戳[{}]", reqInfo, token);
            throw new ServiceException("无效的时间戳");
        }

        //限制访问频率
        int maxFrequency = 60;


        // todo 需要可配置化
        int tolerance = 60 * 5000;
        if (Math.abs(System.currentTimeMillis() - requestTimeMillis) > tolerance) {
            // 延后或者超前
            log.error("[{}]时间戳偏差太大[{}]", reqInfo, token);
            throw new ServiceException("时间戳偏差太大");
        }

        String appSecret = stringRedisTemplate.<String, String>opsForHash()
            .get(RedisSimpleKeyConsts.SaToken.REDIS_KEY_OPEN_API_APP_KEY, deptId);
        if (Objects.isNull(appSecret)) {
            log.error("[{}]未缓存账号密钥[{}]", reqInfo, token);
            throw new ServiceException("未缓存账号密钥");
        }

        String payload = token.substring(0, token.lastIndexOf("|"));
        byte[] userSecretBytes = appSecret.getBytes(StandardCharsets.UTF_8);
        String calcHmac = DigestUtil.hmac(HmacAlgorithm.HmacSHA256, userSecretBytes)
            .digestBase64(payload, true);
        if (Objects.isNull(calcHmac) || !calcHmac.equalsIgnoreCase(sha256)) {
            log.error("[{}]无效的HMAC[{}]预期[{}]实际[{}]", reqInfo, token, sha256, calcHmac);
            throw new ServiceException("无效的HMAC");
        }

        //针对同一个appkey 限制访问频次 目前：1分钟只能1次
        String reqLimitKey = RedisSimpleKeyConsts.SaToken.REDIS_KEY_OPEN_API_REQ_LIMIT_PREFIX + appSecret;
        String reqLimitValue = stringRedisTemplate.opsForValue().get(reqLimitKey);
        if (StringUtils.isNotBlank(reqLimitValue)) {
            throw new ServiceException("接口超过访问频率");
        } else {
            stringRedisTemplate.opsForValue().set(reqLimitKey, "", 60, TimeUnit.SECONDS);
        }


        ThreadLocalHelper.setOpenApiDeptId(Long.valueOf(deptId));
        ThreadLocalHelper.setAppKey(appSecret);
    }


    private void verifyOpenAPIV2(SaRequest request, String token) {
        final String openApiV2LogPrefix = "openApiV2";
        String reqInfo = getReqInfo(request);
        boolean pathVerify = requestPathVerify(request);
        if(!pathVerify){
            log.warn("{}-requestPathVerify校验不通过，reqInfo = {}",openApiV2LogPrefix, reqInfo);
        }
        String[] parts = token.split("\\|");
        if (parts.length < 5) {
            log.error("{}[{}]无效的token[{}]",openApiV2LogPrefix, reqInfo, token);
            throw new ServiceException("无效的token");
        }
        // token = prefix | deptId | nonce | ts | hmac
        String deptId = parts[1];
        String sha256 = parts[4];
        String ts = parts[3];
        long requestTimeMillis;
        try {
            requestTimeMillis = Long.parseLong(ts);
        } catch (Exception e) {
            log.error("{}[{}]无效的时间戳[{}]",openApiV2LogPrefix, reqInfo, token);
            throw new ServiceException("无效的时间戳");
        }

        // todo 需要可配置化
        int tolerance = 60 * 5000;
        if (Math.abs(System.currentTimeMillis() - requestTimeMillis) > tolerance) {
            // 延后或者超前
            log.error("{}[{}]时间戳偏差太大[{}]",openApiV2LogPrefix, reqInfo, token);
            throw new ServiceException("时间戳偏差太大");
        }
        String appSecret = stringRedisTemplate.<String, String>opsForHash()
            .get(RedisSimpleKeyConsts.SaToken.REDIS_KEY_OPEN_API_APP_KEY, deptId);
        if (Objects.isNull(appSecret)) {
            log.error("{}[{}]未缓存账号密钥[{}]",openApiV2LogPrefix, reqInfo, token);
            throw new ServiceException("未缓存账号密钥");
        }

        String payload = token.substring(0, token.lastIndexOf("|"));
        byte[] userSecretBytes = appSecret.getBytes(StandardCharsets.UTF_8);
        String calcHmac = DigestUtil.hmac(HmacAlgorithm.HmacSHA256, userSecretBytes)
            .digestBase64(payload, true);
        if (Objects.isNull(calcHmac) || !calcHmac.equalsIgnoreCase(sha256)) {
            log.error("{}[{}]无效的HMAC[{}]预期[{}]实际[{}]", openApiV2LogPrefix, reqInfo, token, sha256, calcHmac);
            throw new ServiceException("无效的HMAC");
        }

        //针对同一个appkey 限制访问频次
        String reqLimitKey = RedisSimpleKeyConsts.SaToken.REDIS_KEY_OPEN_API_REQ_LIMIT_PREFIX + appSecret;
        String reqLimitValue = stringRedisTemplate.opsForValue().get(reqLimitKey);
        if (StringUtils.isNotBlank(reqLimitValue)) {
            throw new ServiceException("接口超过访问频率");
        } else {
            stringRedisTemplate.opsForValue().set(reqLimitKey, "", 50, TimeUnit.MILLISECONDS);
        }

        ThreadLocalHelper.setOpenApiDeptId(Long.valueOf(deptId));
        ThreadLocalHelper.setAppKey(appSecret);
    }

    private boolean requestPathVerify(SaRequest request) {
        String requestPath = request.getRequestPath();
        Set<String> set = Set.of("/openapi");
        for (String s : set) {
            if(requestPath.contains(s)){
                return true;
            }
        }
        return false;
    }

    private void verifyDevice(SaRequest request, String token) {
        var reqInfo = getReqInfo(request);

        // token = prefix | did | nonce | ts | hmac
        String[] parts = token.split("\\|");
        if (parts.length < 5) {
            log.error("[{}]无效的token[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("无效的token");
        }

        String did = parts[1];
        String nonce = parts[2];
        String ts = parts[3];
        String hmac = parts[4];

        Long deviceInternalId;
        try {
            deviceInternalId = Long.valueOf(did);
        } catch (Exception e) {
            log.error("[{}]无效的设备ID[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("无效的设备ID");
        }

        long requestTimeMillis;
        try {
            requestTimeMillis = Long.parseLong(ts);
        } catch (Exception e) {
            log.error("[{}]无效的时间戳[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("无效的时间戳");
        }

        // todo 需要可配置化
        int tolerance = 60 * 1000;
        if (Math.abs(System.currentTimeMillis() - requestTimeMillis) > tolerance) {
            // 延后或者超前
            log.error("[{}]时间戳偏差太大[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("时间戳偏差太大");
        }

        String deviceSecret = stringRedisTemplate.<String, String>opsForHash()
            .get(RedisSimpleKeyConsts.SaToken.REDIS_KEY_DEVICE_SECRET, did);
        if (Objects.isNull(deviceSecret)) {
            log.error("[{}]未缓存设备密钥[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("未缓存设备密钥");
        }

        String payload = token.substring(0, token.lastIndexOf("|"));
        byte[] deviceSecretBytes = deviceSecret.getBytes(StandardCharsets.UTF_8);
        String calcHmac = DigestUtil.hmac(HmacAlgorithm.HmacSM3, deviceSecretBytes)
            .digestBase64(payload, true);

        if (Objects.isNull(calcHmac) || !calcHmac.equalsIgnoreCase(hmac)) {
            log.error("[{}]无效的HMAC[{}]预期[{}]实际[{}]", reqInfo, token, hmac, calcHmac);
            throw new HmiXUnauthorizedException("无效的HMAC");
        }

        ThreadLocalHelper.setDeviceInternalId(deviceInternalId);
    }
    private String verifyPda(SaRequest request, String token) {
        var reqInfo = getReqInfo(request);

        // token = PDA | pdaCode | nonce | ts | hmac
        String[] parts = token.split("\\|");
        if (parts.length < 5) {
            log.error("[{}]无效的token[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("无效的token");
        }
        String pdaCode = parts[1];
        String nonce = parts[2];
        String ts = parts[3];
        String hmac = parts[4];

        String pdaUniqueId = stringRedisTemplate.<String, String>opsForHash()
            .get(RedisSimpleKeyConsts.SaToken.REDIS_KEY_PDA_UNIQUE_ID, pdaCode);
        if (StringUtils.isBlank(pdaUniqueId)) {
            log.error("[{}]PDA编号不可用[{}]", reqInfo, pdaCode);
            throw new HmiXUnauthorizedException("PDA编号不可用");
        }

        long requestTimeMillis;
        try {
            requestTimeMillis = Long.parseLong(ts);
        } catch (Exception e) {
            log.error("[{}]无效的时间戳[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("无效的时间戳");
        }

        int tolerance = 60 * 1000;
        if (Math.abs(System.currentTimeMillis() - requestTimeMillis) > tolerance) {
            log.error("[{}]时间戳偏差太大[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("时间戳偏差太大");
        }

        String payload = token.substring(0, token.lastIndexOf("|"));
        byte[] keyBytes = pdaUniqueId.getBytes(StandardCharsets.UTF_8);
        String calcHmac = DigestUtil.hmac(HmacAlgorithm.HmacSM3, keyBytes)
            .digestBase64(payload, true);

        if (Objects.isNull(calcHmac) || !calcHmac.equalsIgnoreCase(hmac)) {
            log.error("[{}]无效的HMAC[{}]预期[{}]实际[{}]", reqInfo, token, hmac, calcHmac);
            throw new HmiXUnauthorizedException("无效的HMAC");
        }

        return pdaCode;
    }

    private void verifyDeviceV2(SaRequest request, String token) {
        var reqInfo = getReqInfo(request);

        // token = prefix | deviceName | nonce | ts | hmac
        String[] parts = token.split("\\|");
        if (parts.length < 5) {
            log.error("[{}]无效的token[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("无效的token");
        }

        String deviceName = parts[1];
        String nonce = parts[2];
        String ts = parts[3];
        String hmac = parts[4];

        Long deviceInternalId;
        try {
            var did = stringRedisTemplate.<String, String>opsForHash()
                .get(RedisSimpleKeyConsts.SaToken.REDIS_KEY_DEVICE_NAME_DID, deviceName);
            deviceInternalId = Long.valueOf(did);
        } catch (Exception e) {
            log.error("[{}]无效的设备ID[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("无效的设备ID");
        }

        long requestTimeMillis;
        try {
            requestTimeMillis = Long.parseLong(ts);
        } catch (Exception e) {
            throw new HmiXUnauthorizedException("invalid ts");
        }

        int tolerance = deviceApiToleranceMinutes * 60 * 1000;
        if (Math.abs(System.currentTimeMillis() - requestTimeMillis) > tolerance) {
            // 延后或者超前
            log.error("[{}]无效的时间戳[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("无效的时间戳");
        }

        String deviceSecret = stringRedisTemplate.<String, String>opsForHash()
            .get(RedisSimpleKeyConsts.SaToken.REDIS_KEY_DEVICE_SECRET_V2, deviceName);
        if (Objects.isNull(deviceSecret)) {
            log.error("[{}]未缓存设备密钥[{}]", reqInfo, token);
            throw new HmiXUnauthorizedException("未缓存设备密钥");
        }

        String payload = token.substring(0, token.lastIndexOf("|"));
        byte[] deviceSecretBytes = deviceSecret.getBytes(StandardCharsets.UTF_8);
        String calcHmac = DigestUtil.hmac(HmacAlgorithm.HmacSM3, deviceSecretBytes)
            .digestBase64(payload, true);

        if (Objects.isNull(calcHmac) || !calcHmac.equalsIgnoreCase(hmac)) {
            log.error("[{}]无效的HMAC[{}]预期[{}]实际[{}]", reqInfo, token, hmac, calcHmac);
            throw new HmiXUnauthorizedException("无效的HMAC");
        }

        ThreadLocalHelper.setDeviceInternalId(deviceInternalId);
    }


    public static void main(String[] args) {
        //token = prefix | deptId | nonce | ts | hmac
        String prefix = TOKEN_PREFIX_OF_OPEN_API_V2;
        String deptId = "2058723058424082433";
        Long nonce = RandomUtil.getRandom().nextLong(9999)+1;
        Long ts = System.currentTimeMillis();
        String payload = prefix+"|"+deptId+"|"+nonce+"|"+ts;
        String appKey = "6a1722261a6f532d6dfab1d1fdd47f2ba3f36ee142707463edc34f21d39a4675";
        byte[] userSecretBytes = appKey.getBytes(StandardCharsets.UTF_8);
        String payloadHmac = DigestUtil.hmac(HmacAlgorithm.HmacSHA256, userSecretBytes)
            .digestBase64(payload, true);
        String token = payload+"|"+payloadHmac;
        System.out.println(token);
    }
}

