package com.allthinkstars.framework.iot.ai.tools;

import com.allthinkstars.framework.iot.ai.tools.support.annotation.ToolField;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.ToolFieldAudience;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.NullNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.node.TextNode;
import io.swagger.annotations.ApiModelProperty;
import org.apache.commons.lang3.StringUtils;

import java.lang.reflect.Array;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.time.temporal.Temporal;
import java.util.*;

/**
 * 工具结果双视图投影器
 * 这里统一递归处理字段受众，避免每个 tool 手工拼装 planData / answerData
 */
public final class ToolPayloadProjector {

    private ToolPayloadProjector() {
    }

    public static ToolPayload project(ObjectMapper objectMapper, Object source) {
        AnswerProjection answerProjection = projectForAnswer(objectMapper, source, "", null);
        ObjectNode answerPayload = objectMapper.createObjectNode();
        answerPayload.set("data", answerProjection.data == null ? NullNode.getInstance() : answerProjection.data);
        answerPayload.set("schema", objectMapper.valueToTree(answerProjection.schema));
        return ToolPayload.of(
            projectForPlan(objectMapper, source),
            answerPayload
        );
    }

    private static JsonNode projectForPlan(ObjectMapper objectMapper, Object source) {
        if (source == null) {
            return NullNode.getInstance();
        }
        if (isSimpleValue(source.getClass())) {
            return objectMapper.valueToTree(source);
        }
        if (source instanceof Collection<?>) {
            Collection<?> collection = (Collection<?>) source;
            ArrayNode array = objectMapper.createArrayNode();
            for (Object item : collection) {
                JsonNode projected = projectForPlan(objectMapper, item);
                if (!projected.isMissingNode()) {
                    array.add(projected);
                }
            }
            return array;
        }
        if (source.getClass().isArray()) {
            ArrayNode array = objectMapper.createArrayNode();
            int length = Array.getLength(source);
            for (int i = 0; i < length; i++) {
                array.add(projectForPlan(objectMapper, Array.get(source, i)));
            }
            return array;
        }
        if (source instanceof Map<?, ?>) {
            Map<?, ?> map = (Map<?, ?>) source;
            ObjectNode node = objectMapper.createObjectNode();
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                if (entry.getKey() == null) {
                    continue;
                }
                node.set(String.valueOf(entry.getKey()), projectForPlan(objectMapper, entry.getValue()));
            }
            return node;
        }

        ObjectNode node = objectMapper.createObjectNode();
        for (Field field : allFields(source.getClass())) {
            if (Modifier.isStatic(field.getModifiers()) || field.isSynthetic()) {
                continue;
            }
            field.setAccessible(true);
            try {
                node.set(field.getName(), projectForPlan(objectMapper, field.get(source)));
            } catch (IllegalAccessException e) {
                throw new IllegalStateException("读取工具结果字段失败: " + field.getName(), e);
            }
        }
        return node;
    }

    /**
     * answerData 是给 LLM 消费的语义视图。
     * 这里把 null 统一投影成自然语言占位文案，避免模型把 null 误读成 0、异常或遗漏字段。
     * 但 planData 仍保留原始 null，避免污染后续编排或程序读取的结构化语义。
     */
    private static AnswerProjection projectForAnswer(ObjectMapper objectMapper, Object source, String schemaPath, ToolField currentField) {
        if (source == null) {
            return new AnswerProjection(TextNode.valueOf(resolveNullText(currentField)));
        }
        if (isSimpleValue(source.getClass())) {
            return new AnswerProjection(objectMapper.valueToTree(source));
        }
        if (source instanceof Collection<?>) {
            Collection<?> collection = (Collection<?>) source;
            ArrayNode array = objectMapper.createArrayNode();
            LinkedHashMap<String, String> schema = new LinkedHashMap<>();
            for (Object item : collection) {
                AnswerProjection projected = projectForAnswer(objectMapper, item, schemaPath, null);
                if (!projected.data.isMissingNode()) {
                    array.add(projected.data);
                }
                schema.putAll(projected.schema);
            }
            return new AnswerProjection(array, schema);
        }
        if (source.getClass().isArray()) {
            ArrayNode array = objectMapper.createArrayNode();
            LinkedHashMap<String, String> schema = new LinkedHashMap<>();
            int length = Array.getLength(source);
            for (int i = 0; i < length; i++) {
                AnswerProjection projected = projectForAnswer(objectMapper, Array.get(source, i), schemaPath, null);
                if (!projected.data.isMissingNode()) {
                    array.add(projected.data);
                }
                schema.putAll(projected.schema);
            }
            return new AnswerProjection(array, schema);
        }
        if (source instanceof Map<?, ?>) {
            Map<?, ?> map = (Map<?, ?>) source;
            ObjectNode node = objectMapper.createObjectNode();
            LinkedHashMap<String, String> schema = new LinkedHashMap<>();
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                if (entry.getKey() == null) {
                    continue;
                }
                String key = String.valueOf(entry.getKey());
                AnswerProjection projected = projectForAnswer(objectMapper, entry.getValue(), appendSchemaPath(schemaPath, key), null);
                if (!projected.data.isMissingNode()) {
                    node.set(key, projected.data);
                }
                schema.putAll(projected.schema);
            }
            return new AnswerProjection(node, schema);
        }

        ObjectNode node = objectMapper.createObjectNode();
        LinkedHashMap<String, String> schema = new LinkedHashMap<>();
        for (Field field : allFields(source.getClass())) {
            if (Modifier.isStatic(field.getModifiers()) || field.isSynthetic()) {
                continue;
            }
            ToolField toolField = field.getAnnotation(ToolField.class);
            if (toolField != null && toolField.visibility() == ToolFieldAudience.PLAN_ONLY) {
                continue;
            }
            String answerFieldName = resolveAnswerFieldName(field, toolField);
            String description = resolveDescription(field, toolField);
            String fieldSchemaPath = appendSchemaPath(schemaPath, answerFieldName);
            field.setAccessible(true);
            try {
                AnswerProjection projected = projectForAnswer(objectMapper, field.get(source), fieldSchemaPath, toolField);
                if (!projected.data.isMissingNode()) {
                    node.set(answerFieldName, projected.data);
                    if (StringUtils.isNotBlank(description)) {
                        schema.put(fieldSchemaPath, description.trim());
                    }
                }
                schema.putAll(projected.schema);
            } catch (IllegalAccessException e) {
                throw new IllegalStateException("读取工具结果字段失败: " + field.getName(), e);
            }
        }
        return new AnswerProjection(node, schema);
    }

    private static boolean isSimpleValue(Class<?> type) {
        return type.isPrimitive()
            || CharSequence.class.isAssignableFrom(type)
            || Number.class.isAssignableFrom(type)
            || Boolean.class.isAssignableFrom(type)
            || Date.class.isAssignableFrom(type)
            || UUID.class.isAssignableFrom(type)
            || Enum.class.isAssignableFrom(type)
            || Temporal.class.isAssignableFrom(type)
            || BigDecimal.class.isAssignableFrom(type)
            || BigInteger.class.isAssignableFrom(type);
    }

    private static List<Field> allFields(Class<?> type) {
        List<Field> fields = new ArrayList<>();
        Class<?> current = type;
        while (current != null && current != Object.class) {
            fields.addAll(Arrays.asList(current.getDeclaredFields()));
            current = current.getSuperclass();
        }
        return fields;
    }

    private static String resolveAnswerFieldName(Field field, ToolField toolField) {
        if (toolField != null && StringUtils.isNotBlank(toolField.title())) {
            return toolField.title().trim();
        }
        if (toolField != null && StringUtils.isNotBlank(toolField.label())) {
            return toolField.label().trim();
        }
        ApiModelProperty apiModelProperty = field.getAnnotation(ApiModelProperty.class);
        if (apiModelProperty != null && StringUtils.isNotBlank(apiModelProperty.value())) {
            return apiModelProperty.value().trim();
        }
        return field.getName();
    }

    private static String resolveDescription(Field field, ToolField toolField) {
        if (toolField != null && StringUtils.isNotBlank(toolField.description())) {
            return toolField.description().trim();
        }
        ApiModelProperty apiModelProperty = field.getAnnotation(ApiModelProperty.class);
        if (apiModelProperty != null && StringUtils.isNotBlank(apiModelProperty.value())) {
            return apiModelProperty.value().trim();
        }
        return "";
    }

    private static String resolveNullText(ToolField toolField) {
        if (toolField != null && StringUtils.isNotBlank(toolField.nullText())) {
            return toolField.nullText().trim();
        }
        return "空";
    }

    private static String appendSchemaPath(String prefix, String title) {
        String cleanTitle = title == null ? "" : title.trim();
        if (cleanTitle.isEmpty()) {
            return prefix == null ? "" : prefix;
        }
        if (prefix == null || prefix.trim().isEmpty()) {
            return cleanTitle;
        }
        return prefix.trim() + "." + cleanTitle;
    }

    private static final class AnswerProjection {
        private final JsonNode data;
        private final LinkedHashMap<String, String> schema;

        private AnswerProjection(JsonNode data) {
            this(data, new LinkedHashMap<>());
        }

        private AnswerProjection(JsonNode data, LinkedHashMap<String, String> schema) {
            this.data = data == null ? NullNode.getInstance() : data;
            this.schema = schema == null ? new LinkedHashMap<>() : schema;
        }
    }
}

