package com.allthinkstars.framework.iot.ai.tools;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.NullNode;
import lombok.Data;

/**
 * 工具双视图载荷
 * planData 给规划/编排节点使用，answerData 只给回答节点使用
 */
@Data
public class ToolPayload {
    private JsonNode planData = NullNode.getInstance();
    private JsonNode answerData = NullNode.getInstance();

    public static ToolPayload of(JsonNode planData, JsonNode answerData) {
        ToolPayload payload = new ToolPayload();
        payload.setPlanData(planData == null ? NullNode.getInstance() : planData);
        payload.setAnswerData(answerData == null ? NullNode.getInstance() : answerData);
        return payload;
