    public static ObjectNode buildSchema(ObjectMapper objectMapper, Type type, String description) {
        if (objectMapper == null || type == null) {
            return null;
        }
        JavaType javaType = objectMapper.getTypeFactory().constructType(type);
        return buildSchemaNode(objectMapper, javaType, normalize(description), new HashSet<>());
    }

    private static ObjectNode buildSchemaNode(
        ObjectMapper objectMapper,
        JavaType javaType,
        String explicitDescription,
        Set<String> visiting
    ) {
        ObjectNode node = objectMapper.createObjectNode();
        if (javaType == null) {
            node.put("type", "object");
            return node;
        }
        Class<?> rawClass = javaType.getRawClass();
        if (rawClass == null) {
            node.put("type", "object");
            return node;
        }
        if (StringUtils.isNotBlank(explicitDescription)) {
            node.put("description", explicitDescription.trim());
        }
        if (javaType.isArrayType() || javaType.isCollectionLikeType()) {
            node.put("type", "array");
            JavaType itemType = javaType.getContentType();
            if (itemType == null) {
                itemType = objectMapper.getTypeFactory().constructType(Object.class);
            }
            node.set("items", buildSchemaNode(objectMapper, itemType, "", visiting));
            return node;
        }
        if (javaType.isMapLikeType() || Map.class.isAssignableFrom(rawClass)) {
            node.put("type", "object");
            JavaType valueType = javaType.getContentType();
            if (valueType == null) {
                valueType = objectMapper.getTypeFactory().constructType(Object.class);
            }
            node.set("additionalProperties", buildSchemaNode(objectMapper, valueType, "", visiting));
            return node;
        }
        if (isSimpleValue(rawClass)) {
            node.put("type", inferJsonType(rawClass));
            return node;
        }

        String visitKey = rawClass.getName();
        if (!visiting.add(visitKey)) {
            node.put("type", "object");
            return node;
        }
        try {
            node.put("type", "object");
            ObjectNode properties = objectMapper.createObjectNode();
            for (Field field : allFields(rawClass)) {
                if (Modifier.isStatic(field.getModifiers()) || field.isSynthetic()) {
                    continue;
                }
                ToolField toolField = field.getAnnotation(ToolField.class);
                if (toolField != null && toolField.visibility() == ToolFieldAudience.PLAN_ONLY) {
                    continue;
                }
                ObjectNode property = buildSchemaNode(
                    objectMapper,
                    objectMapper.getTypeFactory().constructType(field.getGenericType()),
                    resolveDescription(field, toolField),
                    visiting
                );
                String label = resolveLabel(field, toolField);
                if (StringUtils.isNotBlank(label)) {
                    property.put("title", label.trim());
                }
                properties.set(field.getName(), property);
            }
            node.set("properties", properties);
            return node;
        } finally {
            visiting.remove(visitKey);
        }
    }

    private static String resolveLabel(Field field, ToolField toolField) {
        if (toolField != null && StringUtils.isNotBlank(toolField.title())) {
            return toolField.title();
        }
        if (toolField != null && StringUtils.isNotBlank(toolField.label())) {
            return toolField.label();
        }
        ApiModelProperty apiModelProperty = field.getAnnotation(ApiModelProperty.class);
        if (apiModelProperty != null && StringUtils.isNotBlank(apiModelProperty.value())) {
            return apiModelProperty.value();
        }
        if (toolField != null && StringUtils.isNotBlank(toolField.description())) {
            return toolField.description();
        }
        return "";
    }

    private static String resolveDescription(Field field, ToolField toolField) {
        if (toolField != null && StringUtils.isNotBlank(toolField.description())) {
            return toolField.description();
        }
        ApiModelProperty apiModelProperty = field.getAnnotation(ApiModelProperty.class);
        if (apiModelProperty != null && StringUtils.isNotBlank(apiModelProperty.value())) {
            return apiModelProperty.value();
        }
        return "";
    }

    private static Map<String, String> extractTopLevelDescriptions(JsonNode schema) {
        Map<String, String> result = new LinkedHashMap<>();
        if (schema == null || !schema.isObject()) {
            return result;
        }
        JsonNode properties = schema.get("properties");
        if (properties == null || !properties.isObject()) {
            return result;
        }
        properties.fields().forEachRemaining(entry -> {
            JsonNode property = entry.getValue();
            if (property != null && property.isObject()) {
                String description = normalize(property.path("description").asText(""));
                if (StringUtils.isNotBlank(description)) {
                    result.put(entry.getKey(), description);
                }
            }
        });
        return result;
    }

    private static String inferJsonType(Class<?> type) {
        if (type == null) {
            return "string";
        }
        if (CharSequence.class.isAssignableFrom(type)
            || type == Character.class
            || type == char.class
            || Date.class.isAssignableFrom(type)
            || Temporal.class.isAssignableFrom(type)
            || UUID.class.isAssignableFrom(type)
            || Enum.class.isAssignableFrom(type)) {
            return "string";
        }
        if (type == boolean.class || type == Boolean.class) {
            return "boolean";
        }
        if (type.isArray() || Collection.class.isAssignableFrom(type)) {
            return "array";
        }
        if (type == float.class || type == double.class || BigDecimal.class.isAssignableFrom(type)) {
            return "number";
        }
        // AI Tool 的 64 位整数和任意精度整数可能超出 JavaScript 安全整数范围，必须以文本契约传递。
        // ToolRegistry 会将文本无感还原为原始 Java 数值类型，业务 DTO 与服务逻辑无需调整。
        if (type == long.class || Long.class.isAssignableFrom(type) || BigInteger.class.isAssignableFrom(type)) {
            return "string";
        }
        if (Number.class.isAssignableFrom(type)
            || type == byte.class || type == short.class || type == int.class) {
            return "integer";
        }
        return "object";
    }

    private static boolean isSimpleValue(Class<?> type) {
        String jsonType = inferJsonType(type);
        return !"object".equals(jsonType) || JsonNode.class.isAssignableFrom(type);
    }

    private static List<Field> allFields(Class<?> type) {
        List<Field> fields = new ArrayList<>();
        Class<?> current = type;
        while (current != null && current != Object.class) {
            fields.addAll(Arrays.asList(current.getDeclaredFields()));
            current = current.getSuperclass();
        }
        return fields;
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim();
    }
}

