/**
 * Java 风味 MCP 到 Pi Tool 的适配层。
 *
 * Java 继续拥有工具目录、鉴权和业务执行；Pi 只将目录转换成自己的 ToolDefinition，
 * 因此工具选择、Agent loop 与工具生命周期完全由 Pi 控制。
 */

import type { ToolDefinition } from "../../coding-agent/src/core/extensions/types.ts";

export interface JavaMcpCallerContext {
	tenantId: string;
	// Java 用户主键可能超过 JavaScript 安全整数范围，必须以十进制字符串跨越 Pi Runtime。
	userId: string;
}

interface JavaMcpToolDescriptor {
	name: string;
	description?: string;
	progressText?: string;
	successText?: string;
	inputSchema?: unknown;
}

/** Tool 展示文案由 Java 业务定义提供，Pi 和前端都不根据工具名猜测业务语义。 */
export interface ToolPresentation {
	progressText: string;
	successText: string;
}

interface JavaMcpEnvelope<T> {
	code?: number;
	msg?: string;
	data?: T;
}

interface JavaMcpListPayload {
	tools?: JavaMcpToolDescriptor[];
}

interface JavaMcpCallPayload {
	ok?: boolean;
	errorCode?: string;
	message?: string;
	preview?: string;
	payload?: unknown;
}

export interface JavaMcpClientOptions {
	baseUrl: string;
	internalToken: string;
	timeoutMs: number;
	fetchImpl?: typeof fetch;
}

export interface CreateJavaMcpToolsOptions {
	conversationId: string;
	caller: JavaMcpCallerContext;
}

class JavaMcpRequestError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "JavaMcpRequestError";
	}
}

function isJsonObject(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function toToolParameters(inputSchema: unknown): Record<string, unknown> {
	if (isJsonObject(inputSchema) && inputSchema.type === "object") return inputSchema;
	return { type: "object", properties: {}, additionalProperties: true };
}

function formatToolResult(payload: JavaMcpCallPayload): string {
	if (payload.ok === false) {
		return `Java tool failed${payload.errorCode ? ` (${payload.errorCode})` : ""}: ${payload.message ?? "unknown error"}`;
	}
	// preview 只适合人读，payload 才是模型继续推理所需的结构化业务结果。
	if (payload.payload !== undefined) return JSON.stringify({ preview: payload.preview, payload: payload.payload });
	if (payload.preview) return payload.preview;
	return payload.message ?? "Java tool completed without a result";
}

export class JavaMcpClient {
	private readonly baseUrl: string;
	private readonly internalToken: string;
	private readonly timeoutMs: number;
	private readonly fetchImpl: typeof fetch;
	private readonly presentationCatalogs = new WeakMap<ToolDefinition[], Record<string, ToolPresentation>>();

	constructor(options: JavaMcpClientOptions) {
		this.baseUrl = options.baseUrl;
		this.internalToken = options.internalToken;
		this.timeoutMs = options.timeoutMs;
		this.fetchImpl = options.fetchImpl ?? fetch;
	}

	async createTools(options: CreateJavaMcpToolsOptions): Promise<ToolDefinition[]> {
		const response = await this.post<JavaMcpListPayload>("/tools/list", {});
		const descriptors = (response.tools ?? []).filter((tool) => tool.name.trim().length > 0);
		const tools = descriptors.map((tool) => this.toPiTool(tool, options));
		this.presentationCatalogs.set(
			tools,
			Object.fromEntries(descriptors.map((tool) => [tool.name, toolPresentation(tool)])),
		);
		return tools;
	}

	/** 返回可安全写入会话 Entry 的紧凑快照，不包含 Tool schema、参数或执行结果。 */
	getPresentationCatalog(tools: ToolDefinition[]): Record<string, ToolPresentation> {
		return this.presentationCatalogs.get(tools) ?? {};
	}

	private toPiTool(tool: JavaMcpToolDescriptor, options: CreateJavaMcpToolsOptions): ToolDefinition {
		const client = this;
		const presentation = toolPresentation(tool);
		return {
			name: tool.name,
			label: tool.name,
			description: tool.description?.trim() || tool.name,
			parameters: toToolParameters(tool.inputSchema),
			async execute(toolCallId, params, signal) {
				const args = isJsonObject(params) ? params : {};
				const response = await client.callTool(
					{
						conversationId: options.conversationId,
						toolCallId,
						toolName: tool.name,
						args,
						context: options.caller,
					},
					signal,
				);
				// Java 已完成 HTTP 调用不代表业务工具执行成功；抛出异常后由 Pi AgentSession 标记为 Tool error。
				if (response.ok === false) throw new JavaMcpRequestError(formatToolResult(response));
				return {
					content: [{ type: "text", text: formatToolResult(response) }],
					details: { ...response, presentation },
				};
			},
		};
	}

	private async callTool(
		body: {
			conversationId: string;
			toolCallId: string;
			toolName: string;
			args: Record<string, unknown>;
			context: JavaMcpCallerContext;
		},
		signal: AbortSignal | undefined,
	): Promise<JavaMcpCallPayload> {
		return this.post<JavaMcpCallPayload>("/tools/call", body, signal);
	}

	private async post<T>(path: string, body: unknown, signal?: AbortSignal): Promise<T> {
		const timeoutSignal = AbortSignal.timeout(this.timeoutMs);
		const response = await this.fetchImpl(`${this.baseUrl}${path}`, {
			method: "POST",
			headers: {
				"Content-Type": "application/json",
				"X-AI-MCP-TOKEN": this.internalToken,
			},
			body: JSON.stringify(body),
			signal: signal ? AbortSignal.any([signal, timeoutSignal]) : timeoutSignal,
		});
		const raw = await response.text();
		let envelope: JavaMcpEnvelope<T>;
		try {
			envelope = JSON.parse(raw) as JavaMcpEnvelope<T>;
		} catch {
			throw new JavaMcpRequestError(`Java MCP returned invalid JSON with status ${response.status}`);
		}
		if (!response.ok || (envelope.code !== undefined && envelope.code !== 200)) {
			throw new JavaMcpRequestError(envelope.msg || `Java MCP request failed with status ${response.status}`);
		}
		if (envelope.data === undefined) throw new JavaMcpRequestError("Java MCP response data is missing");
		return envelope.data;
	}
}

function toolPresentation(tool: JavaMcpToolDescriptor): ToolPresentation {
	return {
		progressText: tool.progressText?.trim() || "正在处理业务请求",
		successText: tool.successText?.trim() || "业务处理已完成",
	};
}

package com.allthinkstars.framework.iot.ai.tools;

import com.allthinkstars.framework.iot.ai.tools.support.AiRunContext;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolDef;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolParam;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import lombok.extern.slf4j.Slf4j;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Parameter;
import java.util.*;

@Slf4j
public class ToolRegistry {

    private final Map<String, ToolMethod> methods = new LinkedHashMap<>();
    private final Map<String, ToolSpec> specs = new LinkedHashMap<>();

    /**
     * 扫描并注册注解式工具方法
     * 注册时会一次性构建：
     * - 可执行方法描述(ToolMethod)
     * - 对外暴露的工具元信息(ToolSpec)
     */
    public void registerAnnotatedBean(ObjectMapper objectMapper, Object toolBean) {
        if (toolBean == null || objectMapper == null) {
            return;
        }
        for (Method method : toolBean.getClass().getDeclaredMethods()) {
            AiToolDef toolDef = method.getAnnotation(AiToolDef.class);
            if (toolDef == null) {
                continue;
            }
            ToolMethod toolMethod = ToolMethod.of(objectMapper, toolBean, method, toolDef);
            String toolName = toolMethod.spec().getName();
            // 同名后注册会覆盖前者，作为显式白名单更新机制
            methods.put(toolName, toolMethod.withSpec(toolMethod.spec().copy()));
            specs.put(toolName, toolMethod.spec().copy());
        }
    }

    /**
     * 工具统一调用入口，负责将异常归一为稳定错误码
     */
    public ToolResult invoke(String toolName, JsonNode args, AiRunContext ctx) {
        ToolMethod method = methods.get(toolName);
        if (method == null) {
            return ToolResults.fail("tool_not_allowed", "工具不在白名单: " + toolName);
        }
        try {
            Object raw = method.invokeRaw(args == null || args.isNull() ? objectMapperFor(method).createObjectNode() : args, ctx);
            return ToolResults.success(objectMapperFor(method), raw);
        } catch (ToolArgsMissingException e) {
            return ToolResults.fail("tool_args_missing", e.getMessage());
        } catch (ToolArgsInvalidException e) {
            return ToolResults.fail("tool_args_invalid", messageOf(e));
        } catch (ToolExecException e) {
            String code = e.getCode() == null || e.getCode().isBlank() ? "tool_exec_failed" : e.getCode();
            return ToolResults.fail(code, messageOf(e));
        } catch (IllegalArgumentException e) {
            String msg = messageOf(e);
            if (msg.startsWith("缺少必填参数:")) {
                return ToolResults.fail("tool_args_missing", msg);
            }
            return ToolResults.fail("tool_args_invalid", msg);
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private ObjectMapper objectMapperFor(ToolMethod method) {
        return method == null ? new ObjectMapper() : method.objectMapper();
    }

    private String messageOf(Throwable throwable) {
        return throwable == null || throwable.getMessage() == null ? String.valueOf(throwable) : throwable.getMessage();
    }

    /**
     * 返回可用于 tools/list 的工具定义快照
     */
    public List<ToolSpec> listToolSpecs() {
        return new ArrayList<>(specs.values());
    }

    public static final class ToolSpec {
        private String name;
        private String title;
        private String description;
        private List<ToolParamSpec> parameters;
        private ToolResultSpec result;

        public ToolSpec(String name, String description, List<ToolParamSpec> parameters) {
            this(name, "", description, parameters, null);
        }

        public ToolSpec(String name, String description, List<ToolParamSpec> parameters, ToolResultSpec result) {
            this(name, "", description, parameters, result);
        }

        public ToolSpec(String name, String title, String description,
                        List<ToolParamSpec> parameters, ToolResultSpec result) {
            this.name = name;
            this.title = title;
            this.description = description;
            this.parameters = parameters;
            this.result = result;
        }

        public String getName() {
            return name;
        }

        public void setName(String name) {
            this.name = name;
        }

        public String getTitle() {
            return title;
        }

        public void setTitle(String title) {
            this.title = title;
        }

        public String getDescription() {
            return description;
        }

        public void setDescription(String description) {
            this.description = description;
        }

        public List<ToolParamSpec> getParameters() {
            return parameters;
        }

        public void setParameters(List<ToolParamSpec> parameters) {
            this.parameters = parameters;
        }

        public ToolResultSpec getResult() {
            return result;
        }

        public void setResult(ToolResultSpec result) {
            this.result = result;
        }

        public ToolSpec copy() {
            List<ToolParamSpec> copied = new ArrayList<>();
            if (parameters != null) {
                for (ToolParamSpec parameter : parameters) {
                    copied.add(new ToolParamSpec(
                        parameter.getName(),
                        parameter.getType(),
                        parameter.isRequired(),
                        parameter.getDescription(),
                        parameter.getTitle(),
                        parameter.getExamples(),
                        parameter.getSchema()
                    ));
                }
            }
            ToolResultSpec copiedResult = result == null ? null : result.copy();
            return new ToolSpec(name, title, description, copied, copiedResult);
        }
    }

    public static final class ToolResultSpec {
        private String description;
        private Map<String, String> fields = new LinkedHashMap<>();
        private JsonNode schema;

        public ToolResultSpec() {
        }

        public ToolResultSpec(String description, Map<String, String> fields) {
            this.description = description;
            if (fields != null) {
                this.fields.putAll(fields);
            }
        }

        public String getDescription() {
            return description;
        }

        public void setDescription(String description) {
            this.description = description;
        }

        public Map<String, String> getFields() {
            return fields;
        }

        public void setFields(Map<String, String> fields) {
            this.fields = fields == null ? new LinkedHashMap<>() : new LinkedHashMap<>(fields);
        }

        public JsonNode getSchema() {
            return schema;
        }

        public void setSchema(JsonNode schema) {
            this.schema = schema == null ? null : schema.deepCopy();
        }

        public ToolResultSpec copy() {
            ToolResultSpec copied = new ToolResultSpec(description, fields);
            copied.setSchema(schema);
            return copied;
        }
    }

    public static final class ToolParamSpec {
        private String name;
        private String type;
        private boolean required;
        private String description;
        private String title;
        private List<String> examples = new ArrayList<>();
        private JsonNode schema;

        public ToolParamSpec(String name, String type, boolean required, String description) {
            this(name, type, required, description, null, null, null);
        }

        public ToolParamSpec(String name, String type, boolean required, String description, String title, List<String> examples) {
            this(name, type, required, description, title, examples, null);
        }

        public ToolParamSpec(String name, String type, boolean required, String description, String title, List<String> examples, JsonNode schema) {
            this.name = name;
            this.type = type;
            this.required = required;
            this.description = description;
            this.title = title;
            if (examples != null && !examples.isEmpty()) {
                this.examples.addAll(examples);
            }
            this.schema = schema == null ? null : schema.deepCopy();
        }

        public String getName() {
            return name;
        }

        public String getType() {
            return type;
        }

        public boolean isRequired() {
            return required;
        }

        public String getDescription() {
            return description;
        }

        public void setDescription(String description) {
            this.description = description;
        }

        public String getTitle() {
            return title;
        }

        public List<String> getExamples() {
            return examples;
        }

        public JsonNode getSchema() {
            return schema == null ? null : schema.deepCopy();
        }
    }

    private static String inferJsonType(Class<?> type) {
        if (type == null) {
            return "string";
        }
        if (CharSequence.class.isAssignableFrom(type) || type == Character.class || type == char.class) {
            return "string";
        }
        if (type == boolean.class || type == Boolean.class) {
            return "boolean";
        }
        if (type.isArray() || java.util.Collection.class.isAssignableFrom(type)) {
            return "array";
        }
        if (type == float.class || type == double.class || type == java.math.BigDecimal.class) {
            return "number";
        }
        // 与嵌套 schema 保持一致，避免直接 Long 参数在模型侧按 JSON number 发生精度丢失。
        if (type == long.class || type == Long.class || type == java.math.BigInteger.class) {
            return "string";
        }
        if (Number.class.isAssignableFrom(type)
            || type == byte.class || type == short.class || type == int.class) {
            return "integer";
        }
        if (JsonNode.class.isAssignableFrom(type)
            || java.util.Map.class.isAssignableFrom(type)
            || type == Object.class) {
            return "object";
        }
        return "string";
    }

    private static final class ToolMethod {
        private final ObjectMapper objectMapper;
        private final Object target;
        private final Method method;
        private final ToolSpec spec;
        private final List<ParameterBinding> bindings;
        private final Set<String> exposedParamNames;

        private ToolMethod(ObjectMapper objectMapper,
                           Object target,
                           Method method,
                           ToolSpec spec,
                           List<ParameterBinding> bindings) {
            this.objectMapper = objectMapper;
            this.target = target;
            this.method = method;
            this.spec = spec;
            this.bindings = bindings;
            this.exposedParamNames = buildExposedParamNames(bindings);
            this.method.setAccessible(true);
        }

        static ToolMethod of(ObjectMapper objectMapper, Object target, Method method, AiToolDef toolDef) {
            String toolName = toolDef.name() == null || toolDef.name().isBlank()
                ? method.getName()
                : toolDef.name().trim();
            List<ParameterBinding> bindings = new ArrayList<>();
            List<ToolParamSpec> params = new ArrayList<>();
            for (Parameter parameter : method.getParameters()) {
                if (AiRunContext.class.isAssignableFrom(parameter.getType())) {
                    bindings.add(ParameterBinding.context(parameter.getType()));
                    continue;
                }
                AiToolParam toolParam = parameter.getAnnotation(AiToolParam.class);
                String paramName = resolveParamName(parameter, toolParam);
                boolean required = parameter.getType().isPrimitive() || (toolParam != null && toolParam.required());
                String description = toolParam == null ? "" : toolParam.value();
                String title = toolParam == null || toolParam.title() == null || toolParam.title().isBlank()
                    ? ""
                    : toolParam.title().trim();
                List<String> examples = buildExamples(toolParam);
                JsonNode schema = ToolSchemaIntrospector.buildSchema(objectMapper, parameter.getParameterizedType(), description);
                String type = schema == null ? inferJsonType(parameter.getType()) : schema.path("type").asText(inferJsonType(parameter.getType()));
                params.add(new ToolParamSpec(paramName, type, required, description, title, examples, schema));
                bindings.add(ParameterBinding.exposed(paramName, parameter.getParameterizedType(), required));
            }
            ToolResultSpec resultSpec = ToolSchemaIntrospector.buildResultSpec(
                objectMapper,
                method.getGenericReturnType(),
                toolDef.outputDescription()
            );
            ToolSpec spec = new ToolSpec(
                toolName,
                toolDef.title(),
                toolDef.value(),
                params,
                resultSpec
            );
            return new ToolMethod(objectMapper, target, method, spec, bindings);
        }

        private static List<String> buildExamples(AiToolParam toolParam) {
            List<String> examples = new ArrayList<>();
            if (toolParam == null) {
                return examples;
            }
            return Arrays.stream(toolParam.examples() == null ? new String[0] : toolParam.examples())
                .filter(Objects::nonNull)
                .map(String::trim)
                .filter(s -> !s.isEmpty())
                .collect(java.util.stream.Collectors.toList());
        }

        ToolMethod withSpec(ToolSpec newSpec) {
            return new ToolMethod(objectMapper, target, method, newSpec, bindings);
        }

        ToolSpec spec() {
            return spec;
        }

        ObjectMapper objectMapper() {
            return objectMapper;
        }

        Object invokeRaw(JsonNode jsonArgs, AiRunContext ctx) throws Exception {
            JsonNode args = jsonArgs == null || jsonArgs.isNull() ? objectMapper.createObjectNode() : jsonArgs;
            // 先拦截未知字段，避免模型 hallucination 参数进入业务方法
            validateUnknownFields(args);
            Object[] argv = bindArgs(args, ctx);
            try {
                return method.invoke(target, argv);
            } catch (InvocationTargetException e) {
                throw rethrowCause(e);
            }
        }

        private Exception rethrowCause(InvocationTargetException e) {
            Throwable cause = e.getTargetException();
            if (cause instanceof Exception) {
                return (Exception) cause;
            }
            return new RuntimeException(cause == null ? e : cause);
        }

        private void validateUnknownFields(JsonNode args) {
            if (args == null || !args.isObject()) {
                return;
            }
            Iterator<String> it = args.fieldNames();
            while (it.hasNext()) {
                String field = it.next();
                if (!exposedParamNames.contains(field)) {
                    throw new IllegalArgumentException("未知参数: " + field);
                }
            }
        }

        private Object[] bindArgs(JsonNode args, AiRunContext ctx) {
            Object[] argv = new Object[bindings.size()];
            for (int i = 0; i < bindings.size(); i++) {
                ParameterBinding binding = bindings.get(i);
                if (binding.contextParam) {
                    // 上下文参数不对外暴露，由 runtime 注入
                    argv[i] = ctx;
                    continue;
                }
                JsonNode value = args.get(binding.name);
                if (value == null || value.isNull()) {
                    if (binding.required) {
                        throw new IllegalArgumentException("缺少必填参数: " + binding.name);
                    }
                    argv[i] = null;
                    continue;
                }
                try {
                    if (JsonNode.class.isAssignableFrom(binding.rawType())) {
                        argv[i] = value;
                    } else {
                        argv[i] = objectMapper.treeToValue(value, objectMapper.constructType(binding.type));
                    }
                } catch (Exception e) {
                    throw new IllegalArgumentException("参数类型不匹配: " + binding.name);
                }
            }
            return argv;
        }

        private static String resolveParamName(Parameter parameter, AiToolParam toolParam) {
            if (toolParam != null && toolParam.name() != null && !toolParam.name().isBlank()) {
                return toolParam.name().trim();
            }
            return parameter.getName();
        }

        private static Set<String> buildExposedParamNames(List<ParameterBinding> bindings) {
            Set<String> names = new LinkedHashSet<>();
            for (ParameterBinding binding : bindings) {
                if (!binding.contextParam) {
                    names.add(binding.name);
                }
            }
            return names;
        }
    }

    private static final class ParameterBinding {
        private final String name;
        private final java.lang.reflect.Type type;
        private final boolean required;
        private final boolean contextParam;

        private ParameterBinding(String name, java.lang.reflect.Type type, boolean required, boolean contextParam) {
            this.name = name;
            this.type = type;
            this.required = required;
            this.contextParam = contextParam;
        }

        static ParameterBinding exposed(String name, java.lang.reflect.Type type, boolean required) {
            return new ParameterBinding(name, type, required, false);
        }

        static ParameterBinding context(java.lang.reflect.Type type) {
            return new ParameterBinding("_ctx_", type, false, true);
        }

        Class<?> rawType() {
            return type instanceof Class<?> ? (Class<?>) type : Object.class;
        }
    }
}

