package com.allthinkstars.framework.iot.ai.tools.support.annotation;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * 标记工具结果字段的视图可见性
 * 当前默认字段会同时进入 planData 和 answerData，只有少量 internal 字段声明为 PLAN_ONLY
 */
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
public @interface ToolField {

    /**
     * 面向 LLM 的字段业务名称，回答阶段优先按该名称理解字段语义。
     */
    String title() default "";

    /**
     * 兼容旧字段名；如同时存在，title 优先。
     */
    @Deprecated
    String label() default "";

    /**
     * 面向 LLM 的字段辅助说明，用于补充 title 未覆盖的业务语义、单位或口径。
     */
    String description() default "";

    /**
     * 回答层遇到字段值为 null 时使用的自然语言占位文案。
     * 默认统一输出“空”，少数字段可按业务语义覆写为“未配置”“未维护”等。
     */
    String nullText() default "空";

    ToolFieldAudience visibility() default ToolFieldAudience.DEFAULT;
}

