package com.allthinkstars.framework.iot.ai.config;

import com.allthinkstars.framework.iot.ai.mcp.context.AiContextResolveService;
import com.allthinkstars.framework.iot.ai.mcp.dispatcher.AiMcpToolDispatcher;
import com.allthinkstars.framework.iot.ai.mcp.dispatcher.AiToolLoginContextRunner;
import com.allthinkstars.framework.iot.ai.mcp.dispatcher.SaTokenAiToolLoginContextRunner;
import com.allthinkstars.framework.iot.ai.mcp.entry.AiMcpEntryService;
import com.allthinkstars.framework.iot.ai.tools.ToolRegistry;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolComponent;
import com.allthinkstars.framework.iot.business.support.IotCommonSupport;
import com.allthinkstars.framework.iot.nextg.mapper.TbDeviceFurnaceMapper;
import com.allthinkstars.framework.iot.nextg.service.UnifiedUserDeptService;
import com.allthinkstars.framework.iot.support.LoginSupport;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.ruoyi.system.mapper.SysDeptMapper;
import com.ruoyi.system.service.ISysUserService;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.factory.ListableBeanFactory;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.util.Map;

@Configuration
@EnableConfigurationProperties(AiProperties.class)
@RequiredArgsConstructor
public class AiAutoConfiguration {

    // 复用应用全局 JSON 规则，确保 MCP 工具结果中的超大 Long 不会在模型侧丢失精度。
    private final ObjectMapper objectMapper;


    @Bean
    public ToolRegistry aiToolRegistry(ListableBeanFactory beanFactory) {
        // 工具白名单注册点：所有模型发出的 tool_call 必须在 registry 中存在才会执行
        // 自动发现所有 @AiToolComponent 工具类，避免在配置层手工维护工具列表
        ToolRegistry registry = new ToolRegistry();
        Map<String, Object> toolBeans = beanFactory.getBeansWithAnnotation(AiToolComponent.class);
        toolBeans.entrySet().stream()
            .sorted(Map.Entry.comparingByKey())
            .forEach(e -> registry.registerAnnotatedBean(objectMapper, e.getValue()));
        return registry;
    }

    @Bean
    public AiContextResolveService aiMcpContextResolverService(IotCommonSupport iotCommonSupport,
                                                               SysDeptMapper sysDeptMapper,
                                                               UnifiedUserDeptService userDeptService,
                                                               TbDeviceFurnaceMapper tbDeviceFurnaceMapper) {
        return new AiContextResolveService(iotCommonSupport, userDeptService, sysDeptMapper, tbDeviceFurnaceMapper);
    }

    @Bean
    public AiToolLoginContextRunner aiToolLoginContextRunner(ISysUserService sysUserService,
                                                             LoginSupport loginSupport) {
        return new SaTokenAiToolLoginContextRunner(sysUserService, loginSupport);
    }

    @Bean
    public AiMcpToolDispatcher aiMcpToolDispatcher(ToolRegistry registry,
                                                   AiContextResolveService contextResolverService,
                                                   AiToolLoginContextRunner loginContextRunner) {
        // dispatcher 负责单次 tools/call 的执行编排与调用审计日志
        return new AiMcpToolDispatcher(registry, objectMapper, contextResolverService, loginContextRunner);
    }

    @Bean
    public AiMcpEntryService aiMcpEntryService(AiProperties props,
                                               ToolRegistry toolRegistry,
                                               AiMcpToolDispatcher toolDispatcher) {
        // entry 是 MCP 对外统一入口，负责 access/authz/list/call 各分支路由
        return new AiMcpEntryService(props, toolRegistry, objectMapper, toolDispatcher);
    }
}

