    /**
     * 使用 JDK 原生流逐段重组 multipart，避免把最多 50 MiB 的图片再次拼成 Java 大字符串或 byte[]。
     * filename 使用稳定序号而不是用户文件名，防止换行等特殊字符污染 multipart 响应头。
     */
    private void writeMultipartRequest(
        HttpURLConnection conn,
        String boundary,
        String query,
        List<MultipartFile> images,
        List<MultipartFile> files
    ) throws IOException {
        conn.setDoOutput(true);
        conn.setChunkedStreamingMode(IO_BUFFER_SIZE);
        try (OutputStream output = conn.getOutputStream()) {
            if (query != null && !query.isBlank()) {
                writeUtf8(output, "--" + boundary + "\r\n");
                writeUtf8(output, "Content-Disposition: form-data; name=\"query\"\r\n");
                writeUtf8(output, "Content-Type: text/plain; charset=UTF-8\r\n\r\n");
                writeUtf8(output, query);
                writeUtf8(output, "\r\n");
            }
            List<MultipartFile> safeImages = images == null ? Collections.emptyList() : images;
            for (int index = 0; index < safeImages.size(); index++) {
                MultipartFile image = safeImages.get(index);
                writeUtf8(output, "--" + boundary + "\r\n");
                writeUtf8(output, "Content-Disposition: form-data; name=\"images\"; filename=\"image-" + (index + 1) + "\"\r\n");
                writeUtf8(output, "Content-Type: " + safeMultipartContentType(image.getContentType()) + "\r\n\r\n");
                try (InputStream input = image.getInputStream()) {
                    copy(input, output, false);
                }
                writeUtf8(output, "\r\n");
            }
            // PDF 使用独立 files 字段转发，避免进入 Pi 的图片解码分支。
            List<MultipartFile> safeFiles = files == null ? Collections.emptyList() : files;
            for (int index = 0; index < safeFiles.size(); index++) {
                MultipartFile file = safeFiles.get(index);
                writeUtf8(output, "--" + boundary + "\r\n");
                writeUtf8(output, "Content-Disposition: form-data; name=\"files\"; filename=\"document-" + (index + 1) + ".pdf\"\r\n");
                writeUtf8(output, "Content-Type: " + safeMultipartContentType(file.getContentType()) + "\r\n\r\n");
                try (InputStream input = file.getInputStream()) {
                    copy(input, output, false);
                }
                writeUtf8(output, "\r\n");
            }
            writeUtf8(output, "--" + boundary + "--\r\n");
            output.flush();
        }
    }

    private void copy(InputStream input, OutputStream output, boolean flushEachChunk) throws IOException {
        if (input == null) {
            output.flush();
            return;
        }
        byte[] buffer = new byte[IO_BUFFER_SIZE];
        int read;
        while ((read = input.read(buffer)) != -1) {
            output.write(buffer, 0, read);
            if (flushEachChunk) {
                output.flush();
            }
        }
        if (!flushEachChunk) {
            output.flush();
        }
    }

    private void writeUtf8(OutputStream output, String value) throws IOException {
        output.write(value.getBytes(StandardCharsets.UTF_8));
    }

