        expected.setToolCallId("call-1");
        expected.setToolName("demo_tool");
        expected.setOk(true);
        when(toolDispatcher.dispatch(req)).thenReturn(expected);

        AiMcpToolsCallResponse actual = entryService.callTool("good-token", req);

        Assert.assertSame(expected, actual);
        verify(toolDispatcher).dispatch(req);
    }

    @Test
    public void callTool_shouldPopulateAndClearAiMdcContext() {
        AiMcpToolsCallRequest req = buildRequest();
        when(toolDispatcher.dispatch(req)).thenAnswer(invocation -> {
